package main
import("context";"runtime";"strconv";"encoding/json";"fmt";"os";"path/filepath";"github.com/johnsonlee/graphite/graphite-server/internal/store";"github.com/johnsonlee/graphite/graphite-server/internal/query")
func main(){fmt.Fprintln(os.Stderr,"runtime.NumCPU=",runtime.NumCPU());ctx:=context.Background();all:=[]map[string]any{};for _,limit:=range []int{255,256}{for _,second:=range []string{"n4096","bad4096"}{a,err:=store.Open(filepath.Join(os.Args[1],"n4096"));if err!=nil{panic(err)};b,err:=store.Open(filepath.Join(os.Args[1],second));if err!=nil{panic(err)};for _,g:=range []*store.Store{a,b}{_,err=query.Execute(ctx,g,"MATCH (n) WHERE n.caller_name CONTAINS 'other' RETURN DISTINCT n.caller_name AS x LIMIT 1",nil,-1);if err!=nil{panic(err)}};q:=fmt.Sprintf("MATCH (n) WHERE n.caller_name CONTAINS 'other' RETURN DISTINCT n.caller_name AS x LIMIT %d",limit);row:=map[string]any{"query":q,"second":second};count:=3;if len(os.Args)>3{count,_=strconv.Atoi(os.Args[3])};sources:=[]query.Graph{};for j:=0;j<count-1;j++{id:="a";if j>0{id=fmt.Sprintf("a%d",j+1)};sources=append(sources,query.Graph{ID:id,Store:a})};sources=append(sources,query.Graph{ID:"b",Store:b});r,err:=query.ExecuteCross(ctx,sources,q,nil,-1);if err!=nil{row["error"]=err.Error()}else{row["columns"]=r.Columns;row["rows"]=r.Rows};all=append(all,row);a.Close();b.Close()}};b,err:=json.MarshalIndent(all,"","  ");if err!=nil{panic(err)};if err=os.WriteFile(os.Args[2],append(b,'\n'),0600);err!=nil{panic(err)}}
